List<Map<String, dynamic>> topUpFeed(dynamic saved, List<Map<String, dynamic>> defaults) {
  final fresh = [for (final post in defaults) Map<String, dynamic>.from(post)];
  if (saved is! List || saved.isEmpty) return fresh;
  final current = <Map<String, dynamic>>[
    for (final item in saved)
      if (item is Map) jsonMap(item),
  ];
  if (current.length >= 20) return current;
  final ids = current.map((post) => post['id']).toSet();
  return [
    ...current,
    for (final post in fresh)
      if (!ids.contains(post['id'])) post,
  ].take(20).toList();
}

